 const scene=new T.Scene(),camera=new T.PerspectiveCamera(39,1,.01,100);let az=.45,el=.28,zoom=6.6;let altitude=550,inclination=53,mode='orbit',elapsed=0,playing=false,speed=180,raf,disposed=false,last=0;let period=0,mean=0,worldRadius=0,closest=0,follow=false;
