 const materialAtlas=new T.TextureLoader().load('assets/space-materials.webp');materialAtlas.colorSpace=T.SRGBColorSpace;materialAtlas.anisotropy=Math.min(renderer.capabilities.getMaxAnisotropy(),8);
 const starPositions=[];let seed=42;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}for(let i=0;i<1600;i++){let a=rand()*TAU,y=rand()*2-1,r=25+rand()*15;starPositions.push(r*Math.sqrt(1-y*y)*Math.cos(a),r*y,r*Math.sqrt(1-y*y)*Math.sin(a))}let starsGeo=new T.BufferGeometry();starsGeo.setAttribute('position',new T.Float32BufferAttribute(starPositions,3));scene.add(new T.Points(starsGeo,new T.PointsMaterial({color:0xb7d0eb,size:.026,transparent:true,opacity:.68,sizeAttenuation:true})));
 const panelCanvas=document.createElement('canvas');panelCanvas.width=512;panelCanvas.height=256;const ctx=panelCanvas.getContext('2d');ctx.fillStyle='#101d44';ctx.fillRect(0,0,512,256);for(let x=0;x<512;x+=32)for(let y=0;y<256;y+=32){ctx.fillStyle=`rgb(${21+rand()*12},${39+rand()*19},${75+rand()*30})`;ctx.fillRect(x+1,y+1,30,30);ctx.strokeStyle='#7487a5';ctx.lineWidth=.5;ctx.strokeRect(x+1,y+1,30,30);ctx.strokeStyle='#3a5679';for(let z=4;z<30;z+=5){ctx.beginPath();ctx.moveTo(x+z,y+1);ctx.lineTo(x+z,y+31);ctx.stroke()}}const panelTexture=new T.CanvasTexture(panelCanvas);panelTexture.colorSpace=T.SRGBColorSpace;
 const gold=new T.MeshStandardMaterial({color:0xd0a960,metalness:.8,roughness:.34});const metal=new T.MeshStandardMaterial({color:0xbecbd4,metalness:.86,roughness:.22});const dark=new T.MeshStandardMaterial({color:0x152b3b,metalness:.6,roughness:.4});const panels=new T.MeshStandardMaterial({map:panelTexture,metalness:.5,roughness:.3,side:T.DoubleSide});
